   247→/// Note: any unknown `u64::into(n)` will resolve to `Goodbye::Unknown` for any unknown `n`,
   248→/// however `GoodbyeReason::Unknown.into()` will go into `0_u64`. Therefore de-serializing then
   249→/// re-serializing may not return the same bytes.
   250→#[derive(Debug, Clone, PartialEq)]
   251→pub enum GoodbyeReason {
   252→    /// This node has shutdown.
   253→    ClientShutdown = 1,
   254→
   255→    /// Incompatible networks.
   256→    IrrelevantNetwork = 2,
   257→
   258→    /// Error/fault in the RPC.
   259→    Fault = 3,
   260→
   261→    /// Teku uses this code for not being able to verify a network.
   262→    UnableToVerifyNetwork = 128,
   263→
   264→    /// The node has too many connected peers.
   265→    TooManyPeers = 129,
   266→
   267→    /// Scored poorly.
   268→    BadScore = 250,
   269→
   270→    /// The peer is banned
   271→    Banned = 251,
   272→
   273→    /// The IP address the peer is using is banned.
   274→    BannedIP = 252,
   275→
   276→    /// Unknown reason.
   277→    Unknown = 0,
   278→}
