   687→
   688→impl<E: EthSpec> RpcResponse<E> {
   689→    /// Used to encode the response in the codec.
   690→    pub fn as_u8(&self) -> Option<u8> {
   691→        match self {
   692→            RpcResponse::Success(_) => Some(0),
   693→            RpcResponse::Error(code, _) => Some(code.as_u8()),
   694→            RpcResponse::StreamTermination(_) => None,
   695→        }
   696→    }
   697→
   698→    /// Tells the codec whether to decode as an RPCResponse or an error.
   699→    pub fn is_response(response_code: u8) -> bool {
   700→        matches!(response_code, 0)
   701→    }
   702→
   703→    /// Builds an RPCCodedResponse from a response code and an ErrorMessage
   704→    pub fn from_error(response_code: u8, err: ErrorType) -> Self {
   705→        let code = match response_code {
   706→            1 => RpcErrorResponse::InvalidRequest,
   707→            2 => RpcErrorResponse::ServerError,
   708→            3 => RpcErrorResponse::ResourceUnavailable,
   709→            139 => RpcErrorResponse::RateLimited,
   710→            140 => RpcErrorResponse::BlobsNotFoundForBlock,
   711→            _ => RpcErrorResponse::Unknown,
   712→        };
   713→        RpcResponse::Error(code, err)
   714→    }
   715→
   716→    /// Returns true if this response always terminates the stream.
   717→    pub fn close_after(&self) -> bool {
   718→        !matches!(self, RpcResponse::Success(_))
   719→    }
   720→}
