   741→            RpcSuccessResponse::BlocksByRoot(_) => Protocol::BlocksByRoot,
   742→            RpcSuccessResponse::BlobsByRange(_) => Protocol::BlobsByRange,
   743→            RpcSuccessResponse::BlobsByRoot(_) => Protocol::BlobsByRoot,
   744→            RpcSuccessResponse::DataColumnsByRoot(_) => Protocol::DataColumnsByRoot,
