   748→            RpcSuccessResponse::LightClientBootstrap(_) => Protocol::LightClientBootstrap,
   749→            RpcSuccessResponse::LightClientOptimisticUpdate(_) => {
   750→                Protocol::LightClientOptimisticUpdate
   751→            }
   752→            RpcSuccessResponse::LightClientFinalityUpdate(_) => Protocol::LightClientFinalityUpdate,
