  1287→    /// Helper function to ensure streamed protocols with multiple responses always end with either
  1288→    /// a stream termination or an error
  1289→    fn terminate_response_stream<R, F: FnOnce(Option<R>) -> Response<T::EthSpec>>(
  1290→        &self,
  1291→        peer_id: PeerId,
  1292→        inbound_request_id: InboundRequestId,
  1293→        result: Result<(), (RpcErrorResponse, &'static str)>,
  1294→        into_response: F,
  1295→    ) {
