  1297→            Ok(_) => self.send_network_message(NetworkMessage::SendResponse {
  1298→                peer_id,
  1299→                inbound_request_id,
  1300→                response: into_response(None),
  1301→            }),
  1302→            Err((error_code, reason)) => {
  1303→                self.send_error_response(peer_id, error_code, reason.into(), inbound_request_id);
  1304→            }
  1305→        }
  1306→    }
  1307→
  1308→    fn record_data_column_request_in_span(
  1309→        &self,
  1310→        peer_id: &PeerId,
  1311→        requested_indices: &[ColumnIndex],
  1312→        epoch_opt: Option<Epoch>,
  1313→        span: Span,
