    )]
    pub async fn handle_blocks_by_range_request(
        self: Arc<Self>,
        peer_id: PeerId,
        inbound_request_id: InboundRequestId,
        req: BlocksByRangeRequest,
    ) {
        let client = self.network_globals.client(&peer_id);
